// A RunR wasm-exec function: a WASI command module on Spin's WAGI executor (CGI).
// The request body is on stdin, the request in the environment (REQUEST_METHOD, PATH_INFO,
// QUERY_STRING, CONTENT_TYPE, HTTP_<HEADER>); the response goes to stdout: CGI headers, a
// blank line, the body. Logs go to stderr. Queue messages and schedule ticks arrive as
// CloudEvents: the HTTP_CE_TYPE variable names the event.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// value of a query parameter (not URL-decoded), "" when absent
static void query_param(const char *name, char *out, size_t size) {
    const char *q = getenv("QUERY_STRING");
    size_t n = strlen(name);
    out[0] = '\0';
    while (q && *q) {
        if (strncmp(q, name, n) == 0 && q[n] == '=') {
            q += n + 1;
            size_t i = 0;
            while (q[i] && q[i] != '&' && i + 1 < size) {
                out[i] = q[i];
                i++;
            }
            out[i] = '\0';
            return;
        }
        q = strchr(q, '&');
        if (q) q++;
    }
}

int main(void) {
    const char *event = getenv("HTTP_CE_TYPE");
    printf("Content-Type: text/plain\n\n");

    if (event && strcmp(event, "dev.runr.schedule.tick") == 0) {
        fprintf(stderr, "tick from C (Wasm)\n");
        printf("tick from C (Wasm)");
        return 0;
    }
    if (event && strcmp(event, "dev.runr.queue.message") == 0) {
        char body[4096];
        size_t len = fread(body, 1, sizeof body - 1, stdin);
        body[len] = '\0';
        printf("processed %s (from C, Wasm)", body);
        return 0;
    }

    char name[128];
    query_param("name", name, sizeof name);
    printf("Hello, %s! (from C, Wasm)", name[0] ? name : "World");
    return 0;
}

package main

import (
	"fmt"
	"io"
	"net/http"

	spinhttp "github.com/spinframework/spin-go-sdk/v2/http"
)

// Every trigger reaches the component as an HTTP request: queue messages and schedule ticks
// arrive as CloudEvents (the ce-type header names the event).
func init() {
	spinhttp.Handle(func(w http.ResponseWriter, r *http.Request) {
		var body string
		switch r.Header.Get("ce-type") {
		case "dev.runr.schedule.tick":
			body = "tick from Go (Wasm)"
		case "dev.runr.queue.message":
			data, _ := io.ReadAll(r.Body)
			body = fmt.Sprintf("processed %s (from Go, Wasm)", data)
		default:
			name := r.URL.Query().Get("name")
			if name == "" {
				name = "World"
			}
			body = fmt.Sprintf("Hello, %s! (from Go, Wasm)", name)
		}
		fmt.Println(body)
		w.Header().Set("Content-Type", "text/plain")
		fmt.Fprint(w, body)
	})
}

// main is required by the compiler; the component's entry point is the handler above.
func main() {}

// Every trigger reaches the component as an HTTP request: queue messages and schedule ticks
// arrive as CloudEvents (the ce-type header names the event).
async function handle(request) {
  const event = request.headers.get('ce-type') || ''
  let body
  if (event === 'dev.runr.schedule.tick') {
    body = 'tick from JavaScript (Wasm)'
  } else if (event === 'dev.runr.queue.message') {
    body = `processed ${await request.text()} (from JavaScript, Wasm)`
  } else {
    const name = new URL(request.url).searchParams.get('name') || 'World'
    body = `Hello, ${name}! (from JavaScript, Wasm)`
  }
  console.log(body)
  return new Response(body, { status: 200, headers: { 'content-type': 'text/plain' } })
}

addEventListener('fetch', (event) => {
  event.respondWith(handle(event.request))
})

